const { takeCopy, returnCopy } = require("./books");
const { chargeFine } = require("./members");
const { daysBetween } = require("./utils/dates");

const LOAN_DAYS = 14;
const FINE_PER_DAY = 0.5;
const loans = new Map();
let nextId = 1;

function lend(memberId, bookId, date) {
  takeCopy(bookId);
  const loan = { id: nextId++, memberId, bookId, date };
  loans.set(loan.id, loan);
  return loan;
}

function giveBack(loanId, date) {
  const loan = loans.get(loanId);
  returnCopy(loan.bookId);
  const late = daysBetween(loan.date, date) - LOAN_DAYS;
  const fine = late * FINE_PER_DAY;
  chargeFine(loan.memberId, fine);
  return { late, fine };
}

module.exports = { lend, giveBack };

