const books = new Map();

function addBook(book) {
  books.set(book.id, { ...book, available: book.copies });
}

function findBook(id) {
  return books.get(id);
}

function takeCopy(id) {
  const book = books.get(id);
  book.available -= 1;
  return book;
}

function returnCopy(id) {
  const book = books.get(id);
  book.available += 1;
}

module.exports = { addBook, findBook, takeCopy, returnCopy };

